DROP TABLE IF EXISTS `Verify`;
CREATE TABLE `Verify` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '唯一标识',
  `type` int NOT NULL DEFAULT '0' COMMENT '类型：\n0-登录\n1-注册\n2-修改登录密码\n3-修改支付密码',
  `phone` bigint NOT NULL COMMENT '手机号',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT '邮箱',
  `Verify` int NOT NULL COMMENT '验证码',
  `date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1771315244443 DEFAULT CHARSET=utf8;

